Sure! Below is a simple implementation of a Connect Four game on a 4x4 board using Rust. This example will include basic functionality such as adding a piece to the board, checking for a win condition, and displaying the board.

```rust
const BOARD_SIZE: usize = 4;

#[derive(Debug, Clone, Copy)]
enum Player {
    None,
    One,
    Two,
}

impl Player {
    fn from_char(c: char) -> Option<Player> {
        match c {
            ' ' => Some(Player::None),
            'X' => Some(Player::One),
            'O' => Some(Player::Two),
            _ => None,
        }
    }

    fn to_char(&self) -> char {
        match self {
            Player::None => ' ',
            Player::One => 'X',
            Player::Two => 'O',
        }
    }
}

struct Board {
    data: [[Player; BOARD_SIZE]; BOARD_SIZE],
}

impl Board {
    fn new() -> Board {
        Board {
            data: [[Player::None; BOARD_SIZE]; BOARD_SIZE],
        }
    }

    fn add_piece(&mut self, col: usize, player: Player) -> bool {
        if col >= BOARD_SIZE {
            return false;
        }

        for row in (0..BOARD_SIZE).rev() {
            if self.data[row][col] == Player::None {
                self.data[row][col] = player;
                return true;
            }
        }

        false
    }

    fn check_win(&self, player: Player) -> bool {
        // Check rows and columns
        for i in 0..BOARD_SIZE {
            if self.check_line(i, 0, 1, 0) || self.check_line(0, i, 0, 1) {
                return true;
            }
        }

        // Check diagonals
        if self.check_line(0, 0, 1, 1) || self.check_line(0, BOARD_SIZE - 1, 1, -1) {
            return true;
        }

        false
    }

    fn check_line(&self, start_row: usize, start_col: usize, row_step: isize, col_step: isize) -> bool {
        let mut count = 0;
        let mut row = start_row as isize;
        let mut col = start_col as isize;

        while row >= 0 && row < BOARD_SIZE as isize && col >= 0 && col < BOARD_SIZE as isize {
            if self.data[row as usize][col as usize] == player {
                count += 1;
                if count == 4 {
                    return true;
                }
            } else {
                count = 0;
            }
            row += row_step;
            col += col_step;
        }

        false
    }

    fn display(&self) {
        for row in &self.data {
            for &player in row {
                print!("{} ", player.to_char());
            }
            println!();
        }
    }
}

fn main() {
    let mut board = Board::new();
    let mut current_player = Player::One;

    loop {
        println!("Player {}'s turn", current_player.to_char());
        board.display();
        let mut col = String::new();
        println!("Enter column (0-3): ");
        std::io::stdin().read_line(&mut col).expect("Failed to read line");
        let col: usize = match col.trim().parse() {
            Ok(num) => num,
            Err(_) => continue,
        };

        if board.add_piece(col, current_player) {
            if board.check_win(current_player) {
                println!("Player {} wins!", current_player.to_char());
                board.display();
                break;
            }
            current_player = match current_player {
                Player::One => Player::Two,
                Player::Two => Player::One,
                Player::None => Player::One,
            };
        } else {
            println!("Column is full, try another one.");
        }
    }
}
```

This code sets up a basic Connect Four game on a 4x4 board. The game alternates between two players, 'X' and 'O', and checks for a win condition after each move. The game continues until a player wins or the board is full. The `add_piece` function places a piece in the specified column, and the `check_win` function checks for a win condition in all possible directions. The `display` function prints the current state of the board.
